  "data",
  "// MoonBit data syntax: mutable fields, record update, struct patterns,\n// tuple structs, labelled constructor fields, default methods, constants\n// and type aliases.\n\nconst START : Int = 10\n\ntypealias Int as Score\n\nstruct Counter {\n  name : String\n  mut count : Score\n}\n\nfn bump(c : Counter) -> Unit {\n  c.count += 1\n}\n\n// a tuple struct, and a newtype\nstruct Pair(Int, Int)\n\ntype Meters Int\n\nstruct Point {\n  x : Int\n  y : Int\n} derive(Show)\n\nfn sum(p : Point) -> Int {\n  match p {\n    { x, y } => x + y\n  }\n}\n\nenum Shape {\n  Rect(width~ : Int, height~ : Int)\n  Circle(Int, label~ : String)\n}\n\nfn area(s : Shape) -> Int {\n  match s {\n    Rect(width~, height~) => width * height\n    Circle(r, ..) => 3 * r * r\n  }\n}\n\ntrait Describe {\n  name(Self) -> String\n  describe(Self) -> String = _\n}\n\n// the default of `describe`\nimpl Describe with describe(self) {\n  \"<\" + self.name() + \">\"\n}\n\nimpl Describe for Point with name(_) {\n  \"point\"\n}\n\nfn main {\n  let c = { name: \"clicks\", count: START }\n  bump(c)\n  bump(c)\n  let copy = { ..c, name: \"copy\" }\n  bump(copy)\n  println(\"\\{c.name} \\{c.count}, \\{copy.name} \\{copy.count}\")\n  let p = Pair(1, 2)\n  match p {\n    Pair(a, b) => println(a + b)\n  }\n  println(Meters(5).0)\n  let pt = { x: 3, y: 4 }\n  println(sum(pt))\n  println({ ..pt, y: 10 })\n  println(area(Rect(height=2, width=5)) + area(Circle(1, label=\"c\")))\n  println(pt.describe())\n}\n\ntest \"counter\" {\n  let c = { name: \"t\", count: 0 }\n  bump(c)\n  assert_eq(c.count, 1)\n}\n"
